  const [g, body] = GG(), fl = [];
  for(let i=0;i<7;i++){ const a = i/7*6.28, m = mesh(geo.dod(.3), i%2 ? mat.leafA : mat.leafB, Math.cos(a)*.32, .08, Math.sin(a)*.32); m.scale.y = .28; m.rotation.y = rng()*3; body.add(m); }
